    # Initialize the path and the visited set
    path = []
    visited = set()

    # Use a stack for depth-first search (DFS)
    stack = [(start, [start])]
    while stack:
        (node, path) = stack.pop()
        if node not in visited:
            if node == goal:
                return path
            visited.add(node)
            # Explore the neighbors in reverse order to ensure we backtrack
            neighbors = reversed(graph.get(node, []))
            for next_node in neighbors:
                if next_node not in visited:
                    stack.append((next_node, path + [next_node]))
    return None
